      this.lookScratch = new T.Vector2();
      this.pendingLook = new T.Vector2();
      this.gamepadLook = new T.Vector2();
      this.mouseLineStartedAt = 0;
      this.mouseLineMotion = 0;
      this.mouseLineCursor = new T.Vector2();
