          const tier = authoredIndex % 4;
          const top = Math.max(ground + 2.8, waterLevel + 2.15 + tier * 4.7);
          const bottom = Math.min(ground - 1.2, top - (family === 1 ? 5.4 : 7.2));
          const height = top - bottom;
