        this.cannon.crystal.getWorldPosition(this.cannon.crystalPosition);
        this.cannon.triggerExterior.position.copy(this.cannon.crystalPosition);
        this.cannon.muzzle.getWorldPosition(this.cannon.muzzlePosition);
