          rail: bestRail,
          distance: bestDistance,
          direction: bestDirection,
          speed: Math.max(26, Math.min(bestRail.cruiseSpeed,
            tangentOf(player.velocity, player.up, this.tangentScratch).length() * 1.15)),
          time: 0,
          lean: 0,
