        boss.attackRadius = 5;
        boss.attackHitSerial = -1;
        boss.telegraph = 0;
        boss.telegraphArmed = false;
        boss.attackRing.visible = true;
        world.particles.burst(boss.position, 0xff70cf, 54, 18, .9, .34);
