        game.player.pitch = pitch;
        game.updateCamera(FIXED_DT);
        game.ball.position.copy(game.readyBallTarget(new T.Vector3()));
        game.stepWith(FIXED_DT, { kick: true, kickPressed: true });
        game.stepWith(FIXED_DT, { kickReleased: true });
